//! `complex` generated by `mlirformat tblgen` (`complex.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "complex.gen.rs"]
mod complex;

#[test]
fn complex_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<complex::Complex>();
    common::Fixtures::check_dialect(&opt, "complex");
}
